#include <iostream>
#include <map>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll number;
    cin >> number;

    map<ll, int> factors;

    for (ll i = 2; i <= number / i; ++i) {
        while (number % i == 0) {
            ++factors[i];
            number /= i;
        }
    }

    if (number > 1) {
        ++factors[number];
    }

    if (factors.size() == 1) {
        cout << factors.begin()->first << '\n';
    } else {
        cout << 1 << '\n';
    }

    return 0;
}

#include <iostream>
#include <set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long number;
    cin >> number;

    set<long long> factors;

    for (long long i = 2; i <= number / i; ++i) {
        if (number % i == 0) {
            factors.insert(i);
            while (number % i == 0) {
                number /= i;
            }
        }
    }

    if (number > 1) {
        factors.insert(number);
    }

    cout << (factors.size() == 1 ? *factors.begin() : 1) << '\n';
    return 0;
}

